class AppColors {
  static const Color olive = Color(0xFF6B8E23);
  static const Color oliveDark = Color(0xFF4A6118);
  static const Color oliveLight = Color(0xFFA3B86C);
  static const Color oliveSurface = Color(0xFFF1F5E4);
  static const Color white = Color(0xFFFFFFFF);
  static const Color textDark = Color(0xFF1F2A10);
}

class AppTheme {
  static ThemeData light(Locale locale) {
    final isArabic = locale.languageCode == 'ar';

    final colorScheme = ColorScheme.fromSeed(
      seedColor: AppColors.olive,
      brightness: Brightness.light,
    ).copyWith(
      primary: AppColors.olive,
      onPrimary: AppColors.white,
      secondary: AppColors.oliveDark,
      onSecondary: AppColors.white,
      surface: AppColors.white,
      onSurface: AppColors.textDark,
      primaryContainer: AppColors.oliveSurface,
      onPrimaryContainer: AppColors.oliveDark,
    );

    final baseTextTheme = ThemeData.light().textTheme;
    final textTheme = isArabic
        ? GoogleFonts.cairoTextTheme(baseTextTheme)
        : GoogleFonts.poppinsTextTheme(baseTextTheme);

    return ThemeData(
      useMaterial3: true,
      colorScheme: colorScheme,
      scaffoldBackgroundColor: AppColors.white,
      textTheme: textTheme.apply(
        bodyColor: AppColors.textDark,
        displayColor: AppColors.textDark,
      ),
      appBarTheme: AppBarTheme(
        backgroundColor: AppColors.olive,
        foregroundColor: AppColors.white,
        elevation: 0,
        centerTitle: true,
        titleTextStyle: textTheme.titleLarge?.copyWith(
          color: AppColors.white,
          fontWeight: FontWeight.w600,
        ),
      ),
      elevatedButtonTheme: ElevatedButtonThemeData(
        style: ElevatedButton.styleFrom(
          backgroundColor: AppColors.olive,
          foregroundColor: AppColors.white,
          minimumSize: const Size.fromHeight(50),
          shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(14)),
        ),
      ),
      outlinedButtonTheme: OutlinedButtonThemeData(
        style: OutlinedButton.styleFrom(
          foregroundColor: AppColors.olive,
          side: const BorderSide(color: AppColors.olive),
          minimumSize: const Size.fromHeight(50),
          shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(14)),
        ),
      ),
      textButtonTheme: TextButtonThemeData(
        style: TextButton.styleFrom(foregroundColor: AppColors.oliveDark),
      ),
      inputDecorationTheme: InputDecorationTheme(
        filled: true,
        fillColor: AppColors.oliveSurface,
        border: OutlineInputBorder(
          borderRadius: BorderRadius.circular(14),
          borderSide: BorderSide.none,
        ),
        focusedBorder: OutlineInputBorder(
          borderRadius: BorderRadius.circular(14),
          borderSide: const BorderSide(color: AppColors.olive, width: 1.5),
        ),
      ),
      floatingActionButtonTheme: const FloatingActionButtonThemeData(
        backgroundColor: AppColors.olive,
        foregroundColor: AppColors.white,
      ),
      cardTheme: CardThemeData(
        color: AppColors.white,
        elevation: 2,
        shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(16)),
      ),
      navigationBarTheme: NavigationBarThemeData(
        backgroundColor: AppColors.white,
        indicatorColor: AppColors.oliveSurface,
        iconTheme: WidgetStateProperty.resolveWith((states) => IconThemeData(
              color: states.contains(WidgetState.selected) ? AppColors.olive : Colors.black45,
            )),
      ),
    );
  }
}

/// ---------------------------------------------------------------------------
/// Locale controller (persists the chosen language)
/// ---------------------------------------------------------------------------
class LocaleController extends ChangeNotifier {
  static const _key = 'app_locale';
  static const supported = [Locale('en'), Locale('ar')];

  Locale _locale = const Locale('ar');
  Locale get locale => _locale;

  Future<void> load() async {
    final prefs = await SharedPreferences.getInstance();
    final code = prefs.getString(_key);
    if (code != null) _locale = Locale(code);
  }

  Future<void> setLocale(Locale locale) async {
    if (!supported.contains(locale)) return;
    _locale = locale;
    notifyListeners();
    final prefs = await SharedPreferences.getInstance();
    await prefs.setString(_key, locale.languageCode);
  }

  Future<void> toggle() =>
      setLocale(_locale.languageCode == 'ar' ? const Locale('en') : const Locale('ar'));
}

