/// ---------------------------------------------------------------------------
/// Entry point
/// ---------------------------------------------------------------------------
Future<void> main() async {
  WidgetsFlutterBinding.ensureInitialized();

  final options = DefaultFirebaseOptions.currentPlatform;
  if (options.apiKey.startsWith('REPLACE_ME')) {
    // Firebase keys were not provided at build time: show a clear message
    // instead of crashing on a blank screen.
    runApp(const _FirebaseNotConfiguredApp());
    return;
  }

  await Firebase.initializeApp(options: options);

  final localeController = LocaleController();
  await localeController.load();

  runApp(MyApp(localeController: localeController, services: AppServices()));
}

class _FirebaseNotConfiguredApp extends StatelessWidget {
  const _FirebaseNotConfiguredApp();

  @override
  Widget build(BuildContext context) {
    return const MaterialApp(
      debugShowCheckedModeBanner: false,
      home: Scaffold(
        body: Center(
          child: Padding(
            padding: EdgeInsets.all(24),
            child: Text(
              'Firebase is not configured.\n'
              'Add your Firebase keys (see lib/firebase_options.dart) and rebuild.',
              textAlign: TextAlign.center,
            ),
          ),
        ),
      ),
    );
  }
}

class MyApp extends StatelessWidget {
  const MyApp({super.key, required this.localeController, required this.services});

  final LocaleController localeController;
  final AppServices services;

  @override
  Widget build(BuildContext context) {
    return ListenableBuilder(
      listenable: localeController,
      builder: (context, _) {
        final locale = localeController.locale;
        return MaterialApp(
          title: 'Olive Fit',
          debugShowCheckedModeBanner: false,
          locale: locale,
          supportedLocales: LocaleController.supported,
          localizationsDelegates: const [
            GlobalMaterialLocalizations.delegate,
            GlobalWidgetsLocalizations.delegate,
            GlobalCupertinoLocalizations.delegate,
          ],
          localeResolutionCallback: (deviceLocale, supportedLocales) {
            for (final l in supportedLocales) {
              if (l.languageCode == deviceLocale?.languageCode) return l;
            }
            return supportedLocales.first;
          },
          theme: AppTheme.light(locale),
          home: AuthGate(services: services, localeController: localeController),
        );
      },
    );
  }
}

/// ---------------------------------------------------------------------------
/// Routes: signed out → Login, signed in without profile → Onboarding, else Home
/// ---------------------------------------------------------------------------
class AuthGate extends StatefulWidget {
  const AuthGate({super.key, required this.services, required this.localeController});

  final AppServices services;
  final LocaleController localeController;

  @override
  State<AuthGate> createState() => _AuthGateState();
}

class _AuthGateState extends State<AuthGate> {
  String? _uid;
  Future<bool>? _onboardingDone;

  Future<bool> _check(String uid) {
    if (_uid != uid || _onboardingDone == null) {
      _uid = uid;
      _onboardingDone = widget.services.profile.hasCompletedOnboarding(uid);
    }
    return _onboardingDone!;
  }

  void _retry() => setState(() => _onboardingDone = null);

  @override
  Widget build(BuildContext context) {
    final isArabic = Localizations.localeOf(context).languageCode == 'ar';

    return StreamBuilder<User?>(
      stream: widget.services.auth.authStateChanges,
      builder: (context, authSnap) {
        if (authSnap.connectionState == ConnectionState.waiting) {
          return const Scaffold(body: Center(child: CircularProgressIndicator()));
        }

        final user = authSnap.data;
        if (user == null) {
          _uid = null;
          _onboardingDone = null;
          return LoginScreen(
            authService: widget.services.auth,
            localeController: widget.localeController,
          );
        }

        return FutureBuilder<bool>(
          future: _check(user.uid),
          builder: (context, snap) {
            if (snap.connectionState != ConnectionState.done) {
              return const Scaffold(body: Center(child: CircularProgressIndicator()));
            }

            if (snap.hasError) {
              return Scaffold(
                body: Center(
                  child: Padding(
                    padding: const EdgeInsets.all(24),
                    child: Column(
                      mainAxisSize: MainAxisSize.min,
                      children: [
                        Text(
                          isArabic
                              ? 'تعذر الاتصال. تحقق من الإنترنت.'
                              : 'Could not connect. Check your internet.',
                          textAlign: TextAlign.center,
                        ),
                        const SizedBox(height: 16),
                        ElevatedButton(
                          onPressed: _retry,
                          child: Text(isArabic ? 'إعادة المحاولة' : 'Retry'),
                        ),
                        TextButton(
                          onPressed: widget.services.auth.signOut,
                          child: Text(isArabic ? 'تسجيل الخروج' : 'Sign out'),
                        ),
                      ],
                    ),
                  ),
                ),
              );
            }

            if (snap.data == true) {
              return HomeShell(
                services: widget.services,
                localeController: widget.localeController,
              );
            }

            return OnboardingScreen(
              authService: widget.services.auth,
              profileService: widget.services.profile,
              onCompleted: () => setState(() => _onboardingDone = Future.value(true)),
            );
          },
        );
      },
    );
  }
}
